/**
 * components/shared/Charts.js: dependency-free SVG chart primitives.
 *
 * Hand-rolled inline-SVG charts (no chart library) sharing the App.css design
 * tokens: SparkLine, BarChart, HBar, DonutChart, plus StatTile / ChartCard
 * layout shells and the fmtNum / fmtSecs / fmtPct formatters. All colors come
 * from CSS vars; callers pass a `color` token, never a literal.
 *
 * Used by: AnalyticsPage, MyMoneyPage, dashboards.
 */
import React, { useState, useCallback, useMemo, useId } from 'react';
import { AlertDiamondIcon } from './Icon';

// ============================================================
// Minimal, sharp chart components - no dependencies
// ============================================================

const SPARK_W = 1000;
const SPARK_H = 100;

/**
 * Line/area sparkline with a hover tooltip.
 *
 * @param {object} props
 * @param {number[]} props.data - the series; needs 2+ points or renders "No data".
 * @param {boolean} [props.fill=true] - shade the area under the line.
 * @param {function} [props.valueFormatter] - formats the tooltip value.
 * @param {string[]} [props.xLabels] - per-point x-axis labels for the tooltip.
 * @param {boolean} [props.signed=false] - opt-in for signed series (e.g. daily
 *        net followers): pins zero into the y-domain, draws a zero baseline, turns
 *        the below-zero stretches of the line+area red, and flags each contiguous
 *        negative-growth period with a warning icon above it. Because the loss days
 *        are tiny next to the gain spikes (a -34 day is ~1px), magnitude alone can't
 *        carry the signal, so color + the icon do. Default keeps the original
 *        relative min->max scale filling to the bottom edge, so every all-positive
 *        caller (views, money) is byte-identical and unaffected.
 * @gotcha Geometry is memoized on `data`/`signed` only and the hooks run before the
 *         early "No data" return, so the Rules of Hooks hold even when data is empty.
 */
export function SparkLine({ data, color = 'var(--orange)', height = 60, fill = true, label, valueFormatter = v => v.toLocaleString(), xLabels = null, signed = false }) {
  const [tooltip, setTooltip] = useState(null);
  const clipId = useId();

  // Memoize geometry - only recompute when data/signed change, not on color/height re-renders.
  // Hooks must be called before any early return (Rules of Hooks).
  const chart = useMemo(() => {
    if (!data || data.length < 2) return null;
    const dataMax = Math.max(...data);
    const dataMin = Math.min(...data);
    // Signed mode forces zero into the domain so the gain/loss divide has a fixed
    // y-position; default mode keeps the original relative min->max scale.
    const lo = signed ? Math.min(0, dataMin) : dataMin;
    const hi = signed ? Math.max(0, dataMax) : dataMax;
    const range = hi - lo || 1;
    const sy = v => SPARK_H - ((v - lo) / range) * (SPARK_H - 8) - 4;
    const pts = data.map((v, i) => ({ x: (i / (data.length - 1)) * SPARK_W, y: sy(v), v }));
    const pathD = `M ${pts.map(p => `${p.x},${p.y}`).join(' L ')}`;
    // Signed: close the area on the zero baseline so it pools above (gain) and below
    // (loss) the line. Default: close on the bottom edge (legacy behavior).
    const zeroY = signed ? sy(0) : null;
    const baseY = signed ? zeroY : SPARK_H;
    const areaD = `M ${pts[0].x},${pts[0].y} L ${pts.map(p => `${p.x},${p.y}`).join(' L ')} L ${SPARK_W},${baseY} L 0,${baseY} Z`;
    // Contiguous runs of loss days -> one warning marker centered over each period.
    // Center as a 0-100% of width so the icon overlay (HTML, not stretched SVG)
    // lands above the run regardless of point count.
    const negRuns = [];
    if (signed) {
      let start = null;
      data.forEach((v, i) => {
        if (v < 0 && start === null) start = i;
        else if (v >= 0 && start !== null) { negRuns.push([start, i - 1]); start = null; }
      });
      if (start !== null) negRuns.push([start, data.length - 1]);
    }
    const negCenters = negRuns.map(([a, b]) => ((a + b) / 2 / (data.length - 1)) * 100);
    return { pts, pathD, areaD, zeroY, negCenters };
  }, [data, signed]);

  const handleMouseMove = useCallback((e) => {
    if (!chart) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = (e.clientX - rect.left) / rect.width;
    const idx = Math.min(Math.round(pct * (data.length - 1)), data.length - 1);
    const pt = chart.pts[idx];
    const xLabel = xLabels ? xLabels[idx] : null;
    setTooltip({ idx, x: pct * 100, y: (pt.y / SPARK_H) * 100, value: pt.v, xLabel });
  }, [chart, data, xLabels]);

  if (!chart) return <div style={{ height, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--dim)', fontSize: 11 }}>No data</div>;

  const { pts, pathD, areaD, zeroY, negCenters } = chart;

  return (
    <div style={{ position: 'relative' }}>
      {label && <div style={{ fontSize: 10, color: 'var(--dim)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 1 }}>{label}</div>}
      <div style={{ position: 'relative' }}
        onMouseMove={handleMouseMove}
        onMouseLeave={() => setTooltip(null)}
      >
        <svg viewBox={`0 0 ${SPARK_W} ${SPARK_H}`} style={{ width: '100%', height, display: 'block' }} preserveAspectRatio="none">
          {fill && signed ? (
            // Same area path clipped twice at the zero line: orange pools above
            // (gain), red pools below (loss). Position-below-baseline is the signal,
            // so the cue survives color-blindness; red only reinforces it.
            <>
              <defs>
                <clipPath id={`${clipId}-pos`}><rect x="0" y="0" width={SPARK_W} height={Math.max(0, zeroY)} /></clipPath>
                <clipPath id={`${clipId}-neg`}><rect x="0" y={zeroY} width={SPARK_W} height={Math.max(0, SPARK_H - zeroY)} /></clipPath>
              </defs>
              <path d={areaD} fill={color} fillOpacity="0.12" clipPath={`url(#${clipId}-pos)`} />
              <path d={areaD} fill="var(--red)" fillOpacity="0.22" clipPath={`url(#${clipId}-neg)`} />
              <line x1="0" y1={zeroY} x2={SPARK_W} y2={zeroY} stroke="var(--border)" strokeWidth="1" vectorEffect="non-scaling-stroke" />
            </>
          ) : fill ? (
            <path d={areaD} fill={color} fillOpacity="0.12" />
          ) : null}
          {signed ? (
            // Draw the line twice, clipped at zero: orange above, red below. The
            // clip cuts the stroke exactly on the baseline, so even a 1px dip shows
            // as a red kink. Color (not depth) is what carries a small loss.
            <>
              <path d={pathD} fill="none" stroke={color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" clipPath={`url(#${clipId}-pos)`} />
              <path d={pathD} fill="none" stroke="var(--red)" strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" clipPath={`url(#${clipId}-neg)`} />
            </>
          ) : (
            <path d={pathD} fill="none" stroke={color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
          )}
          {tooltip && (
            <circle cx={pts[tooltip.idx].x} cy={pts[tooltip.idx].y} r="5" fill={color} vectorEffect="non-scaling-stroke" />
          )}
          {!tooltip && (
            <circle cx={SPARK_W} cy={pts[pts.length-1].y} r="4" fill={color} vectorEffect="non-scaling-stroke" />
          )}
        </svg>
        {signed && zeroY != null && (
          // HTML overlay, not an SVG <text>: the svg is preserveAspectRatio="none"
          // and would stretch a glyph horizontally.
          <span style={{ position: 'absolute', left: 0, top: `${zeroY}%`, transform: 'translateY(-50%)', fontSize: 9, lineHeight: 1, color: 'var(--dim)', pointerEvents: 'none' }}>0</span>
        )}
        {signed && negCenters.map((cx, i) => (
          // One warning glyph centered above each loss period. HTML overlay so the
          // triangle isn't distorted by the non-uniform SVG scaling.
          <span key={i} style={{ position: 'absolute', top: 0, left: `${cx}%`, transform: 'translateX(-50%)', color: 'var(--red)', lineHeight: 0, pointerEvents: 'none' }}>
            <AlertDiamondIcon size={11} />
          </span>
        ))}
        {tooltip && (
          <div style={{
            position: 'absolute',
            top: `${tooltip.y}%`,
            left: `${tooltip.x}%`,
            transform: `translate(${tooltip.x > 80 ? '-110%' : '8px'}, -50%)`,
            background: 'var(--surface3)',
            border: '1px solid var(--border)',
            borderRadius: 4,
            padding: '4px 8px',
            fontSize: 11,
            color: 'var(--white)',
            whiteSpace: 'nowrap',
            pointerEvents: 'none',
            zIndex: 10,
            lineHeight: 1.5,
          }}>
            {tooltip.xLabel && <div style={{ color: 'var(--muted)', fontSize: 10 }}>{tooltip.xLabel}</div>}
            <div>{valueFormatter(tooltip.value)}</div>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Vertical bar chart with hover tooltips.
 * @param {{label: string, value: number}[]} props.data
 * @gotcha Bar heights are scaled into the 30-100% band (not 0-100), so even the
 *         smallest value renders a visible stub rather than a zero-height bar.
 */
export function BarChart({ data, color = 'var(--orange)', height = 80, valueFormatter = v => v }) {
  const [hoveredIdx, setHoveredIdx] = useState(null);
  if (!data || data.length === 0) return <div style={{ height, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--dim)', fontSize: 11 }}>No data</div>;
  const max = Math.max(...data.map(d => d.value)) || 1;
  const min = Math.min(...data.map(d => d.value));
  const range = max - min || 1;
  const barH = height - 16;

  return (
    <div style={{ position: 'relative', height }}>
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 2, height: barH, position: 'absolute', top: 0, left: 0, right: 0 }}>
        {data.map((d, i) => {
          const pct = ((d.value - min) / range) * 70 + 30;
          const isHovered = hoveredIdx === i;
          return (
            <div key={i}
              style={{ flex: 1, height: '100%', display: 'flex', alignItems: 'flex-end', position: 'relative' }}
              onMouseEnter={() => setHoveredIdx(i)}
              onMouseLeave={() => setHoveredIdx(null)}
            >
              <div style={{
                width: '100%',
                height: `${pct}%`,
                background: color,
                borderRadius: '2px 2px 0 0',
                opacity: isHovered ? 1 : 0.9,
                transition: 'height 0.3s ease',
              }} />
              {isHovered && (
                <div style={{
                  position: 'absolute',
                  bottom: `${pct}%`,
                  left: '50%',
                  transform: `translate(${i > data.length * 0.75 ? '-100%' : '-50%'}, -4px)`,
                  background: 'var(--surface3)',
                  border: '1px solid var(--border)',
                  borderRadius: 4,
                  padding: '2px 6px',
                  fontSize: 10,
                  color: 'var(--white)',
                  whiteSpace: 'nowrap',
                  pointerEvents: 'none',
                  zIndex: 10,
                }}>
                  {d.label}: {valueFormatter(d.value)}
                </div>
              )}
            </div>
          );
        })}
      </div>
      <div style={{ display: 'flex', position: 'absolute', bottom: 0, left: 0, right: 0, height: 16 }}>
        {data.map((d, i) => (
          <div key={i} style={{ flex: 1, fontSize: 8, color: 'var(--dim)', textAlign: 'center', lineHeight: '16px', overflow: 'hidden' }}>
            {d.label}
          </div>
        ))}
      </div>
    </div>
  );
}

/** Single horizontal labeled bar (country/gender breakdown rows). value/max set the fill. */
export function HBar({ label, value, max, color = 'var(--orange)', suffix = '%' }) {
  const pct = max > 0 ? (value / max) * 100 : 0;
  return (
    <div style={{ marginBottom: 8 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 3 }}>
        <span style={{ color: 'var(--white)' }}>{label}</span>
        <span style={{ color: 'var(--muted)' }}>{typeof value === 'number' ? value.toLocaleString() : value}{suffix}</span>
      </div>
      <div style={{ height: 4, background: 'var(--surface3)', borderRadius: 2 }}>
        <div style={{ height: '100%', width: `${pct}%`, background: color, borderRadius: 2, transition: 'width 0.4s ease' }} />
      </div>
    </div>
  );
}

/**
 * Donut chart drawn from stroked arcs.
 *
 * @param {{label: string, value: number, color: string}[]} props.segments
 * @param {boolean} [props.hideLabels=false] - skip the floating SVG callouts; use
 *        an external legend instead.
 * @param {{top?: string, bottom: string, color?: string}} [props.centerLabel] -
 *        text rendered in the donut hole (one or two lines).
 * @gotcha Arcs use strokeDasharray/strokeDashoffset on full circles rotated -90deg
 *         so each segment starts where the previous ended; callouts are only drawn
 *         for segments over 3% to avoid label collisions.
 */
export function DonutChart({ segments, size = 80, hideLabels = false, centerLabel = null }) {
  if (!segments || segments.length === 0) return null;
  const total = segments.reduce((s, d) => s + d.value, 0) || 1;
  const r = size * 0.34;
  const cx = size / 2;
  const cy = size / 2;
  const circumference = 2 * Math.PI * r;
  const strokeW = size * 0.1;

  let offset = 0;
  const arcs = segments.map(seg => {
    const pct = seg.value / total;
    const midAngle = -Math.PI / 2 + (offset / circumference + pct / 2) * 2 * Math.PI;
    const arc = { ...seg, pct, offset, dashArray: `${pct * circumference} ${circumference}`, midAngle };
    offset += pct * circumference;
    return arc;
  });

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ overflow: 'visible', display: 'block', margin: '0 auto' }}>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="var(--surface3)" strokeWidth={strokeW} />
      {arcs.map((arc, i) => (
        <circle
          key={i}
          cx={cx} cy={cy} r={r}
          fill="none"
          stroke={arc.color}
          strokeWidth={strokeW}
          strokeDasharray={arc.dashArray}
          strokeDashoffset={-arc.offset}
          style={{ transform: 'rotate(-90deg)', transformOrigin: `${cx}px ${cy}px` }}
        />
      ))}
      {!hideLabels && arcs.filter(arc => arc.pct > 0.03).map((arc, i) => {
        const labelR = r + size * 0.18;
        const lx = cx + labelR * Math.cos(arc.midAngle);
        const ly = cy + labelR * Math.sin(arc.midAngle);
        const anchor = lx < cx ? 'end' : 'start';
        return (
          <g key={i}>
            <text x={lx} y={ly - 6} textAnchor={anchor} fill={arc.color} fontSize={size * 0.09} fontWeight="600">{arc.label}</text>
            <text x={lx} y={ly + size * 0.1} textAnchor={anchor} fill="var(--white)" fontSize={size * 0.085} opacity="0.7">{Math.round(arc.pct * 100)}%</text>
          </g>
        );
      })}
      {centerLabel && (
        centerLabel.top
          ? <g>
              <text x={cx} y={cy - size * 0.05} textAnchor="middle" dominantBaseline="middle" fill="var(--muted)" fontSize={size * 0.08} fontWeight="500">{centerLabel.top}</text>
              <text x={cx} y={cy + size * 0.08} textAnchor="middle" dominantBaseline="middle" fill={centerLabel.color || 'var(--white)'} fontSize={size * 0.12} fontWeight="700">{centerLabel.bottom}</text>
            </g>
          : <text x={cx} y={cy} textAnchor="middle" dominantBaseline="middle" fill={centerLabel.color || 'var(--white)'} fontSize={size * 0.14} fontWeight="700">{centerLabel.bottom}</text>
      )}
    </svg>
  );
}

/** Single stat tile (value + label, optional sub-line and up/down trend). */
export function StatTile({ label, value, sub, color, trend }) {
  return (
    <div className="stat-card">
      <div className={`stat-value ${color || ''}`} style={{ fontSize: 28 }}>{value ?? '—'}</div>
      <div className="stat-label">{label}</div>
      {sub && <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 2 }}>{sub}</div>}
      {trend !== undefined && (
        <div style={{ fontSize: 11, marginTop: 4, color: trend >= 0 ? 'var(--green)' : 'var(--red)' }}>
          {trend >= 0 ? '↑' : '↓'} {Math.abs(trend).toLocaleString()}
        </div>
      )}
    </div>
  );
}

/** Card shell with a title row (optional subtitle + right-aligned `action`). */
export function ChartCard({ title, subtitle, children, action }) {
  return (
    <div className="card" style={{ marginBottom: 16 }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
        <div>
          <h2 className="card-title" style={{ margin: 0 }}>{title}</h2>
          {subtitle && <div style={{ fontSize: 10, color: 'var(--dim)', marginTop: 2, textTransform: 'uppercase', letterSpacing: '0.04em' }}>{subtitle}</div>}
        </div>
        {action}
      </div>
      {children}
    </div>
  );
}

// ── Utility formatters ───────────────────────────────────────────────────────

/**
 * Compact count for an axis or a tile: 1_500_000 -> "1.50M", 12_300 -> "12.3K", null -> "—".
 *
 * A re-export, kept so the chart module's own callers do not have to learn a second name.
 * The format itself is owned by `utils/format.js` fmtCompact, which is the ONE home for how a
 * large count is compacted anywhere in the product.
 */
export { fmtCompact as fmtNum } from '../../utils/format';

/** Seconds -> "2m 5s" (drops the minutes part under 60s), null -> "—". */
export function fmtSecs(s) {
  if (s == null) return '—';
  const m = Math.floor(s / 60);
  const sec = Math.round(s % 60);
  return m > 0 ? `${m}m ${sec}s` : `${sec}s`;
}

/** Fraction -> percent string: 0.123 -> "12.3%", null -> "—". */
export function fmtPct(v) {
  if (v == null) return '—';
  return `${(v * 100).toFixed(1)}%`;
}
