import { BILLED_PAYMENT_VALUES, PAYOUT_DEFAULT_VALUE } from '../../utils/statusValues';
import { PAID_FILTER_CHOICES, PAID_FILTER_ALL, agencyHasPaid, creatorHasBeenPaid, matchesPaidFilter } from '../../utils/paidFilter';
import Badge from './Badge';
import PayoutForm from './PayoutForm';
import SplitBreakdown from './SplitBreakdown';
import { PayoutBadge } from './StatusBadges';
import { fmtDate, fmtMoney, extractMonths, isInKind, round2, todayYMD } from '../../utils/format';
import { campaignLabelParts } from '../../utils/campaignLabel';
import CampaignName from './CampaignName';
import CampaignReference from './CampaignReference';
import ReceiptUpload from './ReceiptUpload';
import AgencySelect from './AgencySelect';
import CreatorFilterChips from './CreatorFilterChips';
import HelpIcon from './HelpIcon';
import { inPeriod, PeriodSelect } from '../../utils/period';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import { useCreators } from '../../hooks/useCreators';
import { uploadPaymentReceipt } from '../../utils/receipt';
import { generateAndUploadIssuedInvoice, loadCurrentDoc } from '../../utils/invoiceDocuments';
import { buildCampaignInvoicePayload, computeProcessingFee, inKindGoodsArrived, invoiceFees, receivedTotal, validateReceiptSums } from '../../utils/invoiceMath';
import ReverseEntryModal from './ReverseEntryModal';
import { fetchJournalEntriesWithLines, findArJe, findCashJe, LockedField, CheckboxLock, PostedBadge, PostedEntries } from './InvoiceLock';
import { useSortState, SortTh } from '../../utils/sort';
import { humanizeError } from '../../utils/errors';
import Feedback from './Feedback';
import InKindRecord from './InKindRecord';
import ReadError from './ReadError';
import EmptyState from './EmptyState';
import { useFormValidation } from '../../hooks/useFormValidation';
import { DB_DATE_MAX, DB_DATE_MIN } from '../../utils/dbLimits';
import Tabs, { tabPanelProps } from './Tabs';
