import { useEffect } from 'react';

/**
 * hooks/useHelpOpen.js - listen for `nys:help-open` and route the dashboard to the help view,
 * remembering where the reader came from.
 *
 * One home for both dashboards. With a copy per dashboard, a component whose audience does not
 * match the dashboard it renders in fails in the gap between the two copies rather than at a
 * seam anybody looks at, and the article simply never opens.
 *
 * @param {object} args
 * @param {string} args.audience 'admin' or 'creator'. An event carrying a different audience is
 *        ignored; an event carrying none is for everyone.
 * @param {Array} args.nav the dashboard's NAV groups, scanned to turn the view the reader was
 *        on into the label the back link shows.
 * @param {function} args.setActiveView state setter for the current view.
 * @param {function} args.setHelpReturnView state setter for `{ view, label }`.
 * @param {function} args.setPendingHelpSlug state setter for the article slug.
 *
 * @gotcha the previous view is read through the `setActiveView` updater rather than from a
 *         captured variable. The listener is registered once, so a captured `activeView` would
 *         be whatever it was at mount and the back link would go to the wrong screen.
 * @gotcha this owns `nys:help-open` ONLY. The five `nys:open-*` deep links are a different
 *         contract with a different consumer and must not move in here.
 * @see components/shared/HelpIcon.js (the dispatcher and the audience default)
 */
export function useHelpOpen({ audience, nav, setActiveView, setHelpReturnView, setPendingHelpSlug }) {
  useEffect(() => {
    function handler(e) {
      const detail = e && e.detail ? e.detail : {};
      if (detail.audience && detail.audience !== audience) return;
      // Capture where the user came from so the help view can offer a back link.
      // Use the latest activeView via the state setter to avoid a stale closure.
      setActiveView((prev) => {
        if (prev !== 'help') {
          let label = prev;
          for (const group of nav || []) {
            const item = (group.items || []).find((i) => i.view === prev);
            if (item) { label = item.label; break; }
          }
          setHelpReturnView({ view: prev, label });
        }
        return 'help';
      });
      setPendingHelpSlug(detail.slug || null);
    }
    if (typeof window !== 'undefined') window.addEventListener('nys:help-open', handler);
    return () => { if (typeof window !== 'undefined') window.removeEventListener('nys:help-open', handler); };
  }, [audience, nav, setActiveView, setHelpReturnView, setPendingHelpSlug]);
}
