/**
 * utils/sort.js - reusable client-side table sorting.
 *
 * One hook (useSortState) plus two presentational helpers (SortIcon, SortTh) so
 * every sortable table shares identical toggle behavior and header affordance.
 * Sorting is comparison-based on values pulled by per-column getter functions,
 * so callers control what each column sorts on without this module knowing the
 * row shape.
 */
import React, { useState } from 'react';

/**
 * Sort state + handlers for a table.
 *
 * @param {string} defaultCol - column key to sort by initially
 * @param {'asc'|'desc'} [defaultDir] - initial direction
 * @returns {{ sortBy, sortDir, toggle, sortRows }} toggle(col) flips direction
 *          when re-clicking the active column, else selects it ascending;
 *          sortRows(rows, getters) returns a sorted COPY (never mutates input).
 */
export function useSortState(defaultCol, defaultDir = 'asc') {
  const [sortBy, setSortBy]   = useState(defaultCol);
  const [sortDir, setSortDir] = useState(defaultDir);
  function toggle(col) {
    if (sortBy === col) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    else { setSortBy(col); setSortDir('asc'); }
  }
  function sortRows(rows, getters) {
    return [...rows].sort((a, b) => {
      const av = getters[sortBy] ? getters[sortBy](a) : '';
      const bv = getters[sortBy] ? getters[sortBy](b) : '';
      if (av < bv) return sortDir === 'asc' ? -1 : 1;
      if (av > bv) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });
  }
  return { sortBy, sortDir, toggle, sortRows };
}

/** Up/down caret shown in a sortable header; dimmed when its column is inactive. */
export function SortIcon({ col, sortBy, sortDir }) {
  const active = sortBy === col;
  return (
    <span style={{ marginLeft: 4, opacity: active ? 1 : 0.3, fontSize: 9 }}>
      {active && sortDir === 'desc' ? '▼' : '▲'}
    </span>
  );
}

/**
 * Sortable `<th>`: the label and its SortIcon inside a real button, in a header that states
 * which way it is sorted.
 *
 * The `<th onClick>` this replaces was the hub's largest mouse-only cluster, 44 call sites
 * across five tables, and it also announced nothing: a screen reader had no way to tell a
 * sorted column from an unsorted one, because no file in the hub used `aria-sort`.
 *
 * @gotcha `aria-sort` belongs on the CELL and the activation on the BUTTON. Putting the
 *         handler on the th and a tabIndex beside it makes a focusable columnheader that
 *         announces as a header rather than as something to press.
 * @see App.css `button.th-sort`
 */
export function SortTh({ col, sortBy, sortDir, onToggle, children }) {
  const active = sortBy === col;
  return (
    <th scope="col" aria-sort={active ? (sortDir === 'asc' ? 'ascending' : 'descending') : 'none'}>
      <button type="button" className="th-sort" onClick={() => onToggle(col)}>
        {children}
        <SortIcon col={col} sortBy={sortBy} sortDir={sortDir} />
      </button>
    </th>
  );
}
