import React, { useEffect, useState } from 'react';
import { fetchExpenseRemaining } from '../../utils/expenseCapacity';
import { fmtMoney } from '../../utils/format';

/**
 * components/shared/SplitExpenseCapacity.js. Live capacity readout + meter for
 * one expense split row.
 *
 * Renders nothing until expenseId is set; then shows a thin meter + readout of
 * how much room is left on the (expense, period). UI mirror of the cap trigger.
 *
 * Used by: components/shared/PayoutForm.js (one per expense-type split row).
 *
 * @invariant the DB trigger fn_check_split_expense_cap is the source of truth;
 *            this only mirrors the math so the user sees the limit before saving.
 * @see utils/expenseCapacity.js, docs/MONEY.md (expense splits)
 */

/**
 * @param {object} props
 * @param {string} props.expenseId
 * @param {string|null} props.expensePeriod - 'YYYY-MM' for recurring, null for one-time
 * @param {string} [props.excludePayoutId] - drops the calling payout's own splits from the committed sum
 * @param {number} [props.formAllocated] - amount this form session already routed to the same (expense, period)
 *        across its OTHER splits (caller computes it so the readout reflects live form state, not just DB)
 * @param {number} [props.thisRowAmount] - the amount on the row being edited
 * @param {function(number)} [props.onRemainingChange] - reports remaining headroom so the caller can clamp input
 */
export default function SplitExpenseCapacity({
  expenseId,
  expensePeriod,
  excludePayoutId,
  formAllocated = 0,
  thisRowAmount = 0,
  onRemainingChange,
}) {
  const [state, setState] = useState({ cap: 0, allocated: 0, expenseName: '', loaded: false });

  useEffect(() => {
    let cancelled = false;
    if (!expenseId) { setState({ cap: 0, allocated: 0, expenseName: '', loaded: false }); return; }
    fetchExpenseRemaining({ expenseId, expensePeriod, excludePayoutId })
      .then(r => { if (!cancelled) setState(r); })
      // A refused read leaves `loaded` false, which hides the meter AND stops the
      // caller being told a headroom. Reporting 0 here clamps the amount input to
      // $0.00 with nothing on screen saying why; the DB trigger is the real cap and
      // still refuses an over-allocated save, so not clamping is the safe direction.
      .catch(() => { if (!cancelled) setState({ cap: 0, allocated: 0, expenseName: '', loaded: false }); });
    return () => { cancelled = true; };
  }, [expenseId, expensePeriod, excludePayoutId]);

  const totalAllocatedByOthers = state.allocated + Math.max(0, formAllocated - thisRowAmount);
  const remaining = Math.max(0, state.cap - totalAllocatedByOthers - thisRowAmount);
  const pctUsed = state.cap > 0 ? Math.min(100, ((totalAllocatedByOthers + thisRowAmount) / state.cap) * 100) : 0;
  const isOver = state.cap > 0 && (totalAllocatedByOthers + thisRowAmount) > state.cap + 0.005;
  const isFull = !isOver && state.cap > 0 && remaining < 0.005;

  useEffect(() => {
    if (!state.loaded) return;
    if (onRemainingChange) onRemainingChange(Math.max(0, state.cap - totalAllocatedByOthers));
  }, [state.loaded, state.cap, totalAllocatedByOthers, onRemainingChange]);

  if (!state.loaded || !expenseId) return null;

  let fillColor = 'var(--muted)';
  if (pctUsed >= 100) fillColor = 'var(--orange)';
  else if (pctUsed >= 70) fillColor = 'var(--orange2)';

  let statusText, statusColor;
  if (isOver) {
    statusText = `OVER by ${fmtMoney((totalAllocatedByOthers + thisRowAmount) - state.cap)}`;
    statusColor = 'var(--red)';
  } else if (isFull) {
    statusText = 'at capacity';
    statusColor = 'var(--orange)';
  } else {
    statusText = `${fmtMoney(remaining)} remaining`;
    statusColor = pctUsed >= 70 ? 'var(--orange2)' : 'var(--muted)';
  }

  return (
    <div className="split-capacity">
      <div className="split-capacity-bar" aria-hidden="true">
        <div className="split-capacity-fill" style={{ width: `${pctUsed}%`, background: fillColor }} />
        {isOver ? <div className="split-capacity-overflow" /> : null}
      </div>
      <div className="split-capacity-readout">
        <span style={{ color: statusColor, fontWeight: 600, letterSpacing: 0.4 }}>{statusText}</span>
        <span className="split-capacity-detail">
          {fmtMoney(totalAllocatedByOthers + thisRowAmount)} of {fmtMoney(state.cap)} allocated
        </span>
      </div>
    </div>
  );
}
