/**
 * components/shared/RateCardEditor.js - author an agency (or default) rate card.
 *
 * A package is a LINE ITEM: a name, the platforms it covers, a quantity label, one price. What
 * you type is exactly what the agency reads, so there is no preview pane and no arithmetic.
 *
 * A card belongs to exactly one owner: an agency, a single shared link, or nobody (the creator
 * DEFAULT). `agencyId` null with no `dashboardId` is not "no agency selected", it IS the
 * default.
 *
 * @invariant `price` is the TOTAL. Never multiplied by `quantity`, never derived from the
 *            platforms. A bundle is simply its own package, which is how the work is sold.
 * @gotcha do not reintroduce derived pricing. Summing per-platform prices cannot express
 *         "$350 TikTok, $450 cross-posted" without an override table that leaks into the UI.
 * @gotcha a prospect is NOT an agency: agencies are created on contract, so a prospect's
 *         pricing hangs off their link. A link card is SEEDED from the default and then edited
 *         freely, never kept in sync, so one price has one home.
 */
import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { useCreators } from '../../hooks/useCreators';
import { humanizeError } from '../../utils/errors';
import { useConfirm } from './ConfirmDialog';
import Feedback from './Feedback';
import EmptyState from './EmptyState';
import Loading from './Loading';
import MoneyInput from './MoneyInput';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from './Refreshing';

const money = (n) => '$' + Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Author a rate card for one agency, or the creator default when agencyId null.
 *
 * @param {object} props
 * @param {string|null} props.agencyId - an agency's card
 * @param {string|null} [props.dashboardId] - one shared link's card
 * @param {string|null} [props.lockCreatorId] - fix the creator (a link has one)
 * @param {string} props.agencyName
 * @param {function} props.onClose
 */
export default function RateCardEditor({ agencyId, dashboardId, lockCreatorId, agencyName, onClose }) {
  const { creators, error: creatorsError } = useCreators();
  const confirm = useConfirm();

  const [creatorId, setCreatorId] = useState('');
  const [platforms, setPlatforms] = useState([]);
  const [card, setCard] = useState(null);
  const [packages, setPackages] = useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  const [error, setError] = useState('');

  useEffect(() => {
    // The tags are a toggle over stored `platform_ids`, so a refused read does not merely
    // drop decoration: a package tagged TikTok renders with no tag at all, and the toggle
    // that would show it is gone. The prices still render, which is why this reports through
    // the editor's own banner rather than replacing the card.
    supabase.from('platforms').select('id, name').order('name')
      .then(({ data, error: platErr }) => {
        if (platErr) { setError(humanizeError(platErr)); setPlatforms([]); return; }
        setPlatforms(data || []);
      });
  }, []);

  useEffect(() => { if (creatorsError) setError(humanizeError(creatorsError)); }, [creatorsError]);

  // A link is already tied to one creator, so there is nothing to choose.
  useEffect(() => {
    if (lockCreatorId) { setCreatorId(lockCreatorId); return; }
    if (!creatorId && creators.length) setCreatorId(creators[0].id);
  }, [creators, creatorId, lockCreatorId]);

  const load = useCallback(async () => {
    // `end()`, not a bare return: useLoadState starts `loading` TRUE where this editor's own
    // flag started false, so a creator that never arrives would spin here forever.
    if (!creatorId) { end(); return; }
    begin();
    setError('');

    // .is('agency_id', null), not .eq: a default card is identified by the
    // ABSENCE of an agency, which .eq(null) cannot express in PostgREST.
    let q = supabase.from('agency_rate_cards')
      .select('id, notes')
      .eq('creator_profile_id', creatorId);
    if (dashboardId)   q = q.eq('dashboard_id', dashboardId);
    else if (agencyId) q = q.eq('agency_id', agencyId).is('dashboard_id', null);
    else               q = q.is('agency_id', null).is('dashboard_id', null);

    const { data: cardRow, error: cardErr } = await q.maybeSingle();
    if (cardErr) { setError(humanizeError(cardErr)); end(); return; }

    setCard(cardRow || null);
    if (!cardRow) { setPackages([]); end(); return; }

    const { data: pkgs, error: pkgErr } = await supabase
      .from('agency_rate_packages')
      .select('id, name, description, quantity, price, platform_ids, sort_order')
      .eq('rate_card_id', cardRow.id)
      .order('sort_order');

    if (pkgErr) { setError(humanizeError(pkgErr)); end(); return; }
    setPackages(pkgs || []);
    end();
  }, [creatorId, agencyId, dashboardId, begin, end]);

  useEffect(() => { load(); }, [load]);

  /**
   * Create this card, optionally seeded from the creator's default.
   *
   * @param {boolean} seed - copy the default card's packages in
   *
   * @gotcha The copy is a snapshot, deliberately. Later edits to the default do
   *         NOT flow through, because a price that two places can change is the
   *         layered model this feature already failed once with.
   */
  const createCard = async (seed) => {
    const { data: created, error: e } = await supabase.from('agency_rate_cards')
      .insert({ agency_id: agencyId ?? null, dashboard_id: dashboardId ?? null, creator_profile_id: creatorId })
      .select('id')
      .single();
    if (e) { setError(humanizeError(e)); return; }

    if (seed) {
      // Seeding COPIES the creator's default card. A refused read here fell
      // through to "no default exists" and created an EMPTY card instead, so an
      // agency would have been quoted a blank price list.
      const { data: def, error: defErr } = await supabase.from('agency_rate_cards')
        .select('id').eq('creator_profile_id', creatorId)
        .is('agency_id', null).is('dashboard_id', null).maybeSingle();
      if (defErr) { setError(humanizeError(defErr)); end(); return; }
      if (def) {
        const { data: src, error: srcErr } = await supabase.from('agency_rate_packages')
          .select('name, description, quantity, unit, price, platform_ids, sort_order')
          .eq('rate_card_id', def.id).order('sort_order');
        if (srcErr) { setError(humanizeError(srcErr)); end(); return; }
        if (src?.length) {
          const { error: copyErr } = await supabase.from('agency_rate_packages')
            .insert(src.map((p) => ({ ...p, rate_card_id: created.id })));
          if (copyErr) { setError(humanizeError(copyErr)); }
        }
      }
    }
    load();
  };

  // @gotcha name must be 1-120 chars (agency_rate_packages_name_len), so a new
  //         row cannot start empty. Inserting '' failed the CHECK and surfaced
  //         as "That value isn't allowed" on a button the user had just pressed.
  const addPackage = async () => {
    const { error: e } = await supabase.from('agency_rate_packages')
      .insert({ rate_card_id: card.id, name: 'New package', quantity: 1, price: 0, platform_ids: [], sort_order: packages.length });
    if (e) { setError(humanizeError(e)); return; }
    load();
  };

  // Optimistic: the row already shows what you typed, so re-fetching would only
  // make a saved field flicker back through its old value.
  const savePackage = async (pkg, patch) => {
    setPackages((cur) => cur.map((p) => (p.id === pkg.id ? { ...p, ...patch } : p)));
    const { error: e } = await supabase.from('agency_rate_packages').update(patch).eq('id', pkg.id);
    if (e) { setError(humanizeError(e)); load(); }
  };

  const deletePackage = async (pkg) => {
    // `body`, NOT `message`. ConfirmDialog reads `body` and drops anything else in silence,
    // so this dialog spent its life asking "Delete package" with no second line and never
    // naming the package.
    const ok = await confirm({
      title: `Delete "${pkg.name || 'this package'}"?`,
      body: 'The package is removed from the rate card. This cannot be undone.',
      danger: true,
    });
    if (!ok) return;
    const { error: e } = await supabase.from('agency_rate_packages').delete().eq('id', pkg.id);
    if (e) { setError(humanizeError(e)); return; }
    load();
  };

  // Three owners, not two: an agency, one shared link, or nobody (the default).
  const owner = dashboardId ? 'link' : (agencyId ? 'agency' : 'default');

  return (
    <div className="detail-panel rc-panel">
      <div className="rc-head">
        <div>
          <div className="rc-title">{owner === 'default' ? 'Default rates' : agencyName}</div>
          <div className="rc-sub">
            {owner === 'default' && 'Every prospect link starts from these. This is exactly what they read.'}
            {owner === 'agency'  && `Only ${agencyName} sees these. This is exactly what they read.`}
            {owner === 'link'    && 'Just this link. Edits here reach nobody else, and the default is left alone.'}
          </div>
        </div>
        <button className="btn btn-ghost btn-sm" onClick={onClose}>Close</button>
      </div>

      <div className="rc-body">
        <Feedback value={error} onDismiss={() => setError('')} />

        <label className="form-label" htmlFor="rc-creator">Creator</label>
        {lockCreatorId ? (
          <div className="form-input" style={{ maxWidth: 260, color: 'var(--muted)', cursor: 'default' }}>
            {creators.find((c) => c.id === lockCreatorId)?.full_name || '\u2014'}
          </div>
        ) : (
          <select
            id="rc-creator"
            className="form-input"
            style={{ maxWidth: 260 }}
            value={creatorId}
            onChange={(e) => setCreatorId(e.target.value)}
          >
            {creators.map((c) => <option key={c.id} value={c.id}>{c.full_name}</option>)}
          </select>
        )}

        {/* `!card` is only an absence when a creator was pickable. A refused creator read
            leaves `creatorId` empty, so `load()` never runs and `card` is null for a card
            nobody looked for. The reason is in the banner above, same as the platform read. */}
        <Refreshing on={refreshing} />
        {loading ? <Loading className="text-muted text-sm" style={{ marginTop: 24 }} /> : creatorsError ? null : !card ? (
          <div className="rc-empty">
            <div className="rc-empty-title">
              {owner === 'link' ? 'This link uses the default rates' : 'No rate card yet'}
            </div>
            <div className="rc-empty-text">
              {owner === 'link'
                ? 'Give it its own copy to quote this prospect something different. The default is not touched, and changes here reach only this link.'
                : 'List what you sell and what it costs. One line per package, including bundles: a TikTok post at $350 and a TikTok + YouTube post at $450 are two lines.'}
            </div>
            <div className="flex items-center gap-8">
              {owner === 'link' && (
                <button className="btn btn-primary" onClick={() => createCard(true)}>Copy the default and edit</button>
              )}
              <button
                className={owner === 'link' ? 'btn btn-ghost' : 'btn btn-primary'}
                onClick={() => createCard(false)}
              >
                {owner === 'link' ? 'Start from empty' : 'Create rate card'}
              </button>
            </div>
          </div>
        ) : (
          <div className="rc-list">
            {packages.length === 0 ? (
              <EmptyState variant="note" style={{ padding: '20px 0' }}
                text="Nothing listed yet. Add your first package below." />
            ) : (
              <div className="rc-rows">
                {packages.map((pkg) => (
                  <PackageRow
                    key={pkg.id}
                    pkg={pkg}
                    platforms={platforms}
                    onSave={savePackage}
                    onDelete={deletePackage}
                    onReject={setError}
                  />
                ))}
              </div>
            )}

            <button className="btn btn-ghost btn-sm" onClick={addPackage}>+ Add package</button>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * One line of the rate card: name, platforms, quantity, price.
 *
 * Every field is CONTROLLED. An uncontrolled box cannot disagree with the person typing into
 * it, so a value the row refused stayed on screen looking saved while `agency_rate_packages`
 * still held the old one, and that number is what an agency is quoted.
 *
 * @invariant after a blur the box shows what the row holds. A refused value is reverted and
 *            reported through the panel's banner, never coerced into a different number.
 */
function PackageRow({ pkg, platforms, onSave, onDelete, onReject }) {
  const [name, setName]   = useState(() => pkg.name || '');
  const [qty, setQty]     = useState(() => String(pkg.quantity ?? 1));
  const [price, setPrice] = useState(() => String(pkg.price ?? 0));

  /* Resync only when the row now holds a DIFFERENT value. A save that succeeded leaves the
     typed text alone, so 1250.50 does not blink to 1250.5 the moment it commits. */
  useEffect(() => { setName((cur) => (cur === pkg.name ? cur : pkg.name || '')); }, [pkg.name]);
  useEffect(() => {
    setQty((cur) => (Number(cur) === Number(pkg.quantity) ? cur : String(pkg.quantity ?? 1)));
  }, [pkg.quantity]);
  useEffect(() => {
    setPrice((cur) => (Number(cur) === Number(pkg.price) ? cur : String(pkg.price ?? 0)));
  }, [pkg.price]);

  const togglePlatform = (id) => {
    const cur = pkg.platform_ids || [];
    onSave(pkg, { platform_ids: cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id] });
  };

  // @gotcha the two bounds mirror agency_rate_packages_qty_positive and
  //         agency_rate_packages_price_nonneg. @see schemas/SCHEMA.sql
  const commitQty = () => {
    const v = parseInt(qty, 10);
    if (!Number.isInteger(v) || v < 1 || v > 1000) {
      setQty(String(pkg.quantity ?? 1));
      onReject('Posts must be a whole number from 1 to 1000. Nothing was saved.');
      return;
    }
    if (v !== Number(pkg.quantity)) onSave(pkg, { quantity: v });
  };

  const commitPrice = () => {
    const v = parseFloat(price);
    if (!Number.isFinite(v) || v < 0 || v > 1000000) {
      setPrice(String(pkg.price ?? 0));
      onReject('Price must be an amount from 0 to 1,000,000. Nothing was saved.');
      return;
    }
    if (v !== Number(pkg.price)) onSave(pkg, { price: v });
  };

  return (
    <div className="rc-row">
      <div className="rc-row-main">
        {/* Clearing the field restores the previous name rather than saving an
            empty one: the DB rejects a blank name, and a rate card line with no
            name is not a thing an agency can read anyway. */}
        <input
          className="form-input rc-row-name"
          aria-label="What this line is called on the rate card"
          value={name}
          maxLength={120}
          placeholder="e.g. TikTok + YouTube, single post"
          onChange={(e) => setName(e.target.value)}
          onBlur={() => {
            const v = name.trim();
            if (!v) { setName(pkg.name || ''); return; }
            if (v !== pkg.name) onSave(pkg, { name: v });
          }}
        />

        <div className="rc-row-tags">
          {platforms.map((p) => {
            const on = (pkg.platform_ids || []).includes(p.id);
            return (
              <button
                key={p.id}
                type="button"
                className={'rc-tag' + (on ? ' rc-tag-on' : '')}
                aria-pressed={on}
                onClick={() => togglePlatform(p.id)}
              >
                {p.name}
              </button>
            );
          })}
        </div>
      </div>

      <div className="rc-row-right">
        <label className="rc-field">
          <span className="rc-field-lbl">Posts</span>
          <input
            className="form-input rc-row-qty"
            type="number"
            min="1"
            max="1000"
            value={qty}
            onChange={(e) => setQty(e.target.value)}
            onBlur={commitQty}
          />
        </label>

        <label className="rc-field">
          <span className="rc-field-lbl">Price</span>
          <MoneyInput
            className="form-input rc-row-price"
            min="0"
            max="1000000"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
            onBlur={commitPrice}
          />
        </label>

        <button className="btn btn-ghost btn-sm rc-del" onClick={() => onDelete(pkg)}>Delete</button>
      </div>

      {/* The agency's eye view of this one line, so there is no separate preview
          pane restating the whole card. */}
      <div className="rc-row-echo">
        {pkg.name || 'Untitled'}
        {pkg.quantity > 1 ? ` · ${pkg.quantity} posts` : ''}
        {' · '}
        <span className="rc-row-echo-price">{money(pkg.price)}</span>
      </div>
    </div>
  );
}
