/**
 * utils/ledger.js - pure ledger reporting utilities (Trial Balance, P&L, Balance Sheet, GL and
 * COA CSV). Every function takes ledger lines, accounts and journal entries and returns
 * computed structures. No DB, no React state.
 *
 * Shapes the CALLER must supply:
 *   account = { id, code, name, type, normal_balance, source_type, profile_id, is_system,
 *               is_active, sort_order }
 *   line    = { id, journal_entry_id, account_id, debit, credit, entry_date, ...metadata }
 *   entry   = { id, entry_date, description, source_type, source_id, reversed_by_je_id, ... }
 *
 * @invariant the caller pre-filters lines to posted, non-reversed entries; these functions do
 *            NOT re-filter. Pass reversal pairs and the totals lie.
 * @see docs/MONEY.md (chart of accounts, report definitions)
 */
import { round2 } from './format';

const ACCOUNT_TYPE_ORDER = ['asset', 'liability', 'equity', 'revenue', 'expense'];

const num = (v) => {
  const n = typeof v === 'number' ? v : parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

// isReversalEntry lives in the dependency-free journalEntry module so light
// callers don't pull @react-pdf/renderer in via this file. Re-exported here
// for discoverability (this is the ledger-reporting home).
export { isReversalEntry } from './journalEntry';

// ── Balance computation ───────────────────────────────────────────────────────

/**
 * Compute the signed balance of an account given its lines.
 * For debit-normal accounts (asset, expense): SUM(debit) - SUM(credit).
 * For credit-normal accounts (liability, equity, revenue): SUM(credit) - SUM(debit).
 * Positive = normal direction, negative = abnormal (contra).
 */
export function getAccountBalance(lines, normalBalance) {
  const totals = (lines || []).reduce(
    (acc, l) => ({ d: acc.d + num(l.debit), c: acc.c + num(l.credit) }),
    { d: 0, c: 0 }
  );
  const bal = normalBalance === 'credit' ? totals.c - totals.d : totals.d - totals.c;
  return round2(bal);
}

// ── Internal: group lines by account ──────────────────────────────────────────

function indexLinesByAccount(lines, asOfDate) {
  const out = new Map();
  const cutoff = asOfDate ? String(asOfDate).slice(0, 10) : null;
  for (const l of lines || []) {
    if (cutoff && l.entry_date && l.entry_date.slice(0, 10) > cutoff) continue;
    if (!out.has(l.account_id)) out.set(l.account_id, []);
    out.get(l.account_id).push(l);
  }
  return out;
}

// ── Trial Balance ─────────────────────────────────────────────────────────────

/**
 * Build trial balance grouped by account type, in code order.
 * Each row carries debit/credit columns + isAbnormal flag.
 * { groups: [{ type, rows: [{ account, debit, credit, isAbnormal }] }],
 *   totalDebit, totalCredit, imbalance, isBalanced }
 */
export function buildTrialBalance(accounts, lines, asOfDate, opts = {}) {
  const { includeZero = false } = opts;
  const byAccount = indexLinesByAccount(lines, asOfDate);

  const sorted = [...(accounts || [])].sort((a, b) => {
    const ai = ACCOUNT_TYPE_ORDER.indexOf(a.type);
    const bi = ACCOUNT_TYPE_ORDER.indexOf(b.type);
    if (ai !== bi) return ai - bi;
    return String(a.code || '').localeCompare(String(b.code || ''));
  });

  const groupMap = new Map();
  let totalDebit = 0;
  let totalCredit = 0;

  for (const acct of sorted) {
    const accLines = byAccount.get(acct.id) || [];
    const totals = accLines.reduce(
      (a, l) => ({ d: a.d + num(l.debit), c: a.c + num(l.credit) }),
      { d: 0, c: 0 }
    );
    const net = round2(totals.d - totals.c); // raw debit-side net

    let debit = 0;
    let credit = 0;
    let isAbnormal = false;

    if (acct.normal_balance === 'debit') {
      if (net >= 0) debit = net;
      else { credit = Math.abs(net); isAbnormal = net < 0; }
    } else {
      if (net <= 0) credit = Math.abs(net);
      else { debit = net; isAbnormal = net > 0; }
    }

    if (!includeZero && debit === 0 && credit === 0) continue;

    if (!groupMap.has(acct.type)) groupMap.set(acct.type, []);
    groupMap.get(acct.type).push({ account: acct, debit, credit, isAbnormal });

    totalDebit  = round2(totalDebit  + debit);
    totalCredit = round2(totalCredit + credit);
  }

  const groups = ACCOUNT_TYPE_ORDER
    .filter((t) => groupMap.has(t))
    .map((t) => ({ type: t, rows: groupMap.get(t) }));

  const imbalance = round2(totalDebit - totalCredit);
  return { groups, totalDebit, totalCredit, imbalance, isBalanced: imbalance === 0 };
}

// ── Year-end close ────────────────────────────────────────────────────────────

/**
 * Drop every line belonging to a year-end close entry (Pattern K).
 *
 * @param {Array<{id: string, source_type: string}>} entries the JEs those lines belong to
 * @param {Array<{journal_entry_id: string}>} lines
 * @returns {Array} `lines` with the close entry's own lines removed
 *
 * @invariant an income statement EXCLUDES the close entry, a balance sheet
 *   INCLUDES it. One rule, two halves, and this is the excluding half. Close
 *   zeroes every revenue and expense account into 3900 retained earnings dated
 *   Dec 31, so a P&L that counts it reports a closed year as $0.00 on every
 *   line while Form 1065 reports the real figures. A balance sheet and
 *   Schedule L want exactly that closed retained-earnings position, so they
 *   must NOT call this.
 * @gotcha a line carries no source_type of its own, so `entries` is not
 *   optional context: it is the only way to tell a close line from any other.
 * @see docs/MONEY.md Pattern K
 */
export function excludeYearEndCloseLines(entries, lines) {
  const closeIds = new Set(
    (entries || []).filter((e) => e && e.source_type === 'year_end_close').map((e) => e.id)
  );
  return (lines || []).filter((l) => !closeIds.has(l.journal_entry_id));
}

// ── P&L Report ────────────────────────────────────────────────────────────────

/**
 * Build a Profit and Loss report. Returns { revenue, costOfRevenue, operatingExpenses,
 * totalRevenue, totalCostOfRevenue, totalOperatingExpenses, grossProfit, netIncome }. Splitting
 * revenue into cash vs in-kind is the caller's job; it renders the subheads.
 *
 * Classification: revenue is type='revenue'; costOfRevenue is type='expense' with a code
 * starting '5'; operatingExpenses is every other expense.
 *
 * @gotcha rows are signed by their SECTION, not by the account's own normal_balance: revenue is
 *         always credits minus debits, expenses always debits minus credits. 4900 Sales Returns
 *         is type='revenue' with normal_balance='debit', correct for contra-revenue, so signing
 *         it naturally makes a refund ADD to revenue and overstates net income by twice the
 *         refund. A contra account belongs in its section as a negative number, which is also
 *         how a P&L reads.
 */
export function buildPLReport(accounts, lines) {
  const byAccount = indexLinesByAccount(lines, null);
  const rowFor = (acct, sectionSide) => ({
    account: acct,
    balance: getAccountBalance(byAccount.get(acct.id) || [], sectionSide),
  });

  const revenue = [];
  const costOfRevenue = [];
  const operatingExpenses = [];

  for (const acct of accounts || []) {
    if (acct.type === 'revenue') revenue.push(rowFor(acct, 'credit'));
    else if (acct.type === 'expense') {
      const code = String(acct.code || '');
      if (code.startsWith('5')) costOfRevenue.push(rowFor(acct, 'debit'));
      else operatingExpenses.push(rowFor(acct, 'debit'));
    }
  }

  const sumBy = (rows) => round2(rows.reduce((s, r) => s + r.balance, 0));
  const totalRevenue = sumBy(revenue);
  const totalCostOfRevenue = sumBy(costOfRevenue);
  const totalOperatingExpenses = sumBy(operatingExpenses);
  const grossProfit = round2(totalRevenue - totalCostOfRevenue);
  const netIncome = round2(grossProfit - totalOperatingExpenses);

  const sortRows = (rows) => rows.sort((a, b) =>
    String(a.account.code || '').localeCompare(String(b.account.code || ''))
  );

  return {
    revenue: sortRows(revenue),
    costOfRevenue: sortRows(costOfRevenue),
    operatingExpenses: sortRows(operatingExpenses),
    totalRevenue,
    totalCostOfRevenue,
    totalOperatingExpenses,
    grossProfit,
    netIncome,
  };
}

// ── Balance Sheet ─────────────────────────────────────────────────────────────

/**
 * Build a Balance Sheet.
 * @returns {{assets, liabilities, equity, totalAssets, totalLiabilities,
 *           totalEquity, isBalanced}}
 * @gotcha net income for the current OPEN year is not folded into a real equity
 *         account until close_fiscal_year() runs. For mid-year display we add a
 *         synthetic 3950 "Current Period Earnings" equity row so A = L + E still
 *         balances; that row is display-only and never posted.
 */
export function buildBalanceSheet(accounts, lines, asOfDate) {
  const byAccount = indexLinesByAccount(lines, asOfDate);
  const rowFor = (acct) => ({
    account: acct,
    balance: getAccountBalance(byAccount.get(acct.id) || [], acct.normal_balance),
  });

  const assets = [];
  const liabilities = [];
  const equity = [];
  let revenueTotal = 0;
  let expenseTotal = 0;

  for (const acct of accounts || []) {
    if (acct.type === 'asset') assets.push(rowFor(acct));
    else if (acct.type === 'liability') liabilities.push(rowFor(acct));
    else if (acct.type === 'equity') equity.push(rowFor(acct));
    else if (acct.type === 'revenue') {
      revenueTotal = round2(revenueTotal + getAccountBalance(byAccount.get(acct.id) || [], 'credit'));
    } else if (acct.type === 'expense') {
      expenseTotal = round2(expenseTotal + getAccountBalance(byAccount.get(acct.id) || [], 'debit'));
    }
  }

  const currentEarnings = round2(revenueTotal - expenseTotal);
  if (currentEarnings !== 0) {
    equity.push({
      account: { id: '__current_earnings__', code: '3950', name: 'Current Period Earnings', type: 'equity', normal_balance: 'credit' },
      balance: currentEarnings,
    });
  }

  const sumBy = (rows) => round2(rows.reduce((s, r) => s + r.balance, 0));
  const totalAssets = sumBy(assets);
  const totalLiabilities = sumBy(liabilities);
  const totalEquity = sumBy(equity);
  const isBalanced = round2(totalAssets - totalLiabilities - totalEquity) === 0;

  const sortRows = (rows) => rows.sort((a, b) =>
    String(a.account.code || '').localeCompare(String(b.account.code || ''))
  );

  return {
    assets: sortRows(assets),
    liabilities: sortRows(liabilities),
    equity: sortRows(equity),
    totalAssets,
    totalLiabilities,
    totalEquity,
    isBalanced,
  };
}

// ── CSV serializers (BOM-prefixed for Excel) ──────────────────────────────────

const BOM = '﻿';

/**
 * @security a cell whose first character is =, +, -, @, tab or CR is EXECUTED as a formula by
 *           Excel, LibreOffice and Sheets when the file is opened, and these exports are
 *           opened on the admin workstation. Quoting is about CSV parsing and does nothing
 *           about that, so the value is prefixed with an apostrophe, which those three read as
 *           "this cell is text".
 * @gotcha the apostrophe goes INSIDE the quotes when the value also needs quoting. Outside,
 *         the cell parses as a stray apostrophe followed by a quoted field and the
 *         neutralisation is lost.
 */
const FORMULA_LEAD = /^[=+\-@\t\r]/;

function csvCell(v) {
  if (v == null) return '';
  let s = String(v);
  if (FORMULA_LEAD.test(s)) s = `'${s}`;
  if (/[",\n\r]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
  return s;
}

function csvRow(cells) {
  return cells.map(csvCell).join(',');
}

/**
 * General Ledger CSV. Caller passes the same data the GL tab is rendering;
 * we apply the filters ourselves so the export stays in sync with the view.
 */
export function formatGeneralLedgerCsv(entries, lines, accounts, filters = {}) {
  const { dateFrom, dateTo, accountId, sourceTypes, search } = filters;
  const accountById = new Map((accounts || []).map((a) => [a.id, a]));
  const entryById = new Map((entries || []).map((e) => [e.id, e]));

  const sourceFilter = sourceTypes && sourceTypes.length ? new Set(sourceTypes) : null;
  const searchLc = search ? String(search).toLowerCase() : null;

  const filtered = (lines || []).filter((l) => {
    const e = entryById.get(l.journal_entry_id);
    if (!e) return false;
    const d = (e.entry_date || '').slice(0, 10);
    if (dateFrom && d < dateFrom) return false;
    if (dateTo   && d > dateTo)   return false;
    if (accountId && l.account_id !== accountId) return false;
    if (sourceFilter && !sourceFilter.has(e.source_type)) return false;
    if (searchLc && !(e.description || '').toLowerCase().includes(searchLc)) return false;
    return true;
  });

  const header = csvRow([
    'entry_date', 'je_id', 'description', 'source_type', 'source_id',
    'account_code', 'account_name', 'debit', 'credit',
    'reconciliation_id', 'reversed_by_je_id', 'created_by', 'created_at',
  ]);

  const body = filtered.map((l) => {
    const e = entryById.get(l.journal_entry_id) || {};
    const a = accountById.get(l.account_id) || {};
    return csvRow([
      e.entry_date || '', e.id || '', e.description || '', e.source_type || '', e.source_id || '',
      a.code || '', a.name || '',
      num(l.debit).toFixed(2), num(l.credit).toFixed(2),
      l.reconciliation_id || '', e.reversed_by_je_id || '',
      e.created_by || '', e.created_at || '',
    ]);
  });

  return BOM + [header, ...body].join('\n') + '\n';
}

/**
 * Chart of Accounts CSV.
 */
export function formatChartOfAccountsCsv(accounts) {
  const header = csvRow([
    'code', 'name', 'type', 'normal_balance', 'source_type',
    'profile_id', 'is_system', 'is_active', 'sort_order',
  ]);
  const sorted = [...(accounts || [])].sort((a, b) =>
    String(a.code || '').localeCompare(String(b.code || ''))
  );
  const body = sorted.map((a) => csvRow([
    a.code || '', a.name || '', a.type || '', a.normal_balance || '',
    a.source_type || '', a.profile_id || '',
    a.is_system ? 'true' : 'false',
    a.is_active === false ? 'false' : 'true',
    a.sort_order ?? 0,
  ]));
  return BOM + [header, ...body].join('\n') + '\n';
}

