/**
 * hooks/useFormValidation.js - tiny declarative per-field form validation.
 *
 * A pre-save guard that stops an obviously bad value from making a round-trip.
 * It is NOT the source of truth; the DB CHECK constraints are. Mirror them here,
 * do not invent rules the DB will not enforce.
 *
 * Used by: invoice / payout / expense / rewards forms across the hub.
 *
 * @invariant the rule set should track the DB CHECKs it mirrors (e.g. the
 *            [] date window); drift means the UI accepts a
 *            value the DB then rejects with a raw error.
 * @see docs/CODEBASE.md (error / feedback system)
 */
import { useState, useCallback, useId, useMemo } from 'react';
import { isValidDateString, isValidNumber, isValidEmail, isValidUrl } from '../utils/format';

/**
 * @param {Object<string, object>} rules - per-field rule objects. Supported keys:
 *        required, number (+min/max), date (+dateBetween [lo,hi]), email, url,
 *        maxLength, custom(value)=>msg|null, and message (per-field override).
 * @returns {{errors, validate, validateField, clear, fieldProps, errorProps, setErrors}}
 *
 * @example
 *   const v = useFormValidation({
 *     invoice_amount:    { required: true, number: true, min: 0.01, message: 'Enter a positive amount.' },
 *     you_received_date: { date: true, dateBetween: ['', ''] },
 *     notes:             { maxLength: 2000 },
 *   });
 *   const ok = v.validate(form);     // true/false; populates v.errors
 *   v.fieldProps('invoice_amount');  // { 'aria-invalid', 'aria-describedby' }
 *   v.errorProps('invoice_amount');  // { className, id, role } for the visible message
 *   v.clear('invoice_amount');       // wipe one field's error (call on change)
 */
export function useFormValidation(rules) {
  const [errors, setErrors] = useState({});

  const validateField = useCallback((name, value) => {
    const rule = rules[name];
    if (!rule) return null;
    const empty = value === '' || value == null;

    if (rule.required && empty) return rule.message || 'Required.';
    if (empty) return null; // optional fields skip remaining checks

    if (rule.number) {
      if (!isValidNumber(value)) return rule.message || 'Enter a number.';
      const n = parseFloat(value);
      if (rule.min != null && n < rule.min) return rule.message || `Must be at least ${rule.min}.`;
      if (rule.max != null && n > rule.max) return rule.message || `Must be at most ${rule.max}.`;
    }

    if (rule.date) {
      if (!isValidDateString(value)) return rule.message || 'Enter a valid date.';
      if (rule.dateBetween) {
        const [lo, hi] = rule.dateBetween;
        if (value < lo || value > hi) return rule.message || `Date must be between ${lo} and ${hi}.`;
      }
    }

    if (rule.email && !isValidEmail(value)) return rule.message || 'Enter a valid email.';
    if (rule.url   && !isValidUrl(value))   return rule.message || 'Enter a valid URL.';

    if (rule.maxLength != null && String(value).length > rule.maxLength) {
      return rule.message || `Maximum ${rule.maxLength} characters.`;
    }

    if (typeof rule.custom === 'function') {
      const msg = rule.custom(value);
      if (msg) return msg;
    }

    return null;
  }, [rules]);

  const validate = useCallback((values) => {
    const next = {};
    for (const name of Object.keys(rules)) {
      const msg = validateField(name, values?.[name]);
      if (msg) next[name] = msg;
    }
    setErrors(next);
    return Object.keys(next).length === 0;
  }, [rules, validateField]);

  const clear = useCallback((name) => {
    setErrors((e) => {
      if (!e[name]) return e;
      const { [name]: _gone, ...rest } = e;
      return rest;
    });
  }, []);

  // One prefix per hook instance, so two forms on screen at once cannot mint the same id and
  // point both fields at one message.
  const idPrefix = useId();
  const errorId = useCallback((name) => `${idPrefix}-${name}-error`, [idPrefix]);

  const fieldProps = useCallback(
    (name) => ({
      'aria-invalid': errors[name] ? true : undefined,
      // Only while there IS a message: a describedby pointing at an element that is not
      // rendered is announced as nothing, and `aria-invalid` alone says "wrong" without why.
      'aria-describedby': errors[name] ? errorId(name) : undefined,
    }),
    [errors, errorId]
  );

  /**
   * The props for the visible message, so the id it needs and the id the field points at are
   * minted in ONE place. Spread it: `<div {...v.errorProps('invoice_date')}>{...}</div>`.
   */
  const errorProps = useCallback(
    (name) => ({ className: 'field-error', id: errorId(name), role: 'alert' }),
    [errorId]
  );

  return useMemo(
    () => ({ errors, validate, validateField, clear, fieldProps, errorProps, setErrors }),
    [errors, validate, validateField, clear, fieldProps, errorProps]
  );
}
