/**
 * components/shared/Sidebar.js: primary nav for both dashboards.
 *
 * Desktop: collapsible left rail (collapse state in localStorage). Mobile
 * (<=768px): bottom tab bar (first 4 items of section 0) + a "More" drawer for
 * the rest. Shared by AdminDashboard + CreatorDashboard via the navItems prop.
 *
 * @param {Array} props.navItems - [{ label, items: [{ view, label, icon }] }]
 * @param {Object} [props.statusDots] - { [view]: 'failed'|'degraded' } health
 *        dots; the worst dot of any drawer-buried item surfaces on the More tab.
 * @see components/shared/HealthBeacon.js (statusDots source)
 */
import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { useIdle } from '../../contexts/IdleContext';

function fmtIdle(secs) {
  if (secs == null) return null;
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

const MORE_ICON = (
  <svg width="20" height="20" viewBox="0 0 20 20" fill="currentColor">
    <circle cx="3.5" cy="3.5" r="1.5"/><circle cx="10" cy="3.5" r="1.5"/><circle cx="16.5" cy="3.5" r="1.5"/>
    <circle cx="3.5" cy="10"  r="1.5"/><circle cx="10" cy="10"  r="1.5"/><circle cx="16.5" cy="10"  r="1.5"/>
    <circle cx="3.5" cy="16.5" r="1.5"/><circle cx="10" cy="16.5" r="1.5"/><circle cx="16.5" cy="16.5" r="1.5"/>
  </svg>
);

export default function Sidebar({ navItems, activeView, setActiveView, statusDots }) {
  const { profile, signOut } = useAuth();
  const { secondsLeft } = useIdle();
  const [collapsed, setCollapsed] = useState(
    () => localStorage.getItem('sidebar-collapsed') === 'true'
  );
  const [isMobile, setIsMobile]       = useState(() => window.innerWidth <= 768);
  const [drawerOpen, setDrawerOpen]   = useState(false);
  const [drawerVisible, setDrawerVisible] = useState(false);
  const closeTimer = useRef(null);

  useEffect(() => {
    localStorage.setItem('sidebar-collapsed', collapsed);
  }, [collapsed]);

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setIsMobile(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  function openDrawer() {
    if (closeTimer.current) { clearTimeout(closeTimer.current); closeTimer.current = null; }
    setDrawerOpen(true);
    requestAnimationFrame(() => setDrawerVisible(true));
  }

  function closeDrawer(callback) {
    setDrawerVisible(false);
    closeTimer.current = setTimeout(() => {
      setDrawerOpen(false);
      closeTimer.current = null;
      if (callback) callback();
    }, 240);
  }

  function navigateFrom(view) {
    closeDrawer(() => setActiveView(view));
  }

  // Worst status among nav items not shown as a primary mobile tab - surfaced
  // on the "More" tab so a flagged item buried in the drawer is still visible.
  function moreTabStatus(primaryItems) {
    if (!statusDots) return null;
    const buried = Object.keys(statusDots).filter(v => !primaryItems.some(p => p.view === v));
    const vals = buried.map(v => statusDots[v]);
    return vals.includes('failed') ? 'failed' : vals.includes('degraded') ? 'degraded' : null;
  }

  if (isMobile) {
    const primaryItems = navItems[0]?.items?.slice(0, 4) || [];
    const isMoreActive = !primaryItems.some(item => item.view === activeView);
    const moreStatus   = moreTabStatus(primaryItems);

    const remainingFirst = navItems[0]?.items?.slice(4) || [];
    const drawerSections = [
      ...(remainingFirst.length > 0 ? [{ label: null, items: remainingFirst }] : []),
      ...navItems.slice(1),
    ].filter(s => s.items.length > 0);

    const shortLabel = label => label.replace(/^My /, '');

    return (
      <>
        <div className="mobile-bottom-nav">
          {primaryItems.map(item => (
            <button
              key={item.view}
              className={`mobile-nav-tab${activeView === item.view ? ' active' : ''}`}
              onClick={() => setActiveView(item.view)}
            >
              <span className="mobile-nav-tab-icon">
                {item.icon}
                {statusDots?.[item.view] && (
                  <span className={`health-dot health-dot--${statusDots[item.view]} nav-status-dot nav-status-dot--corner`} aria-hidden />
                )}
              </span>
              <span className="mobile-nav-tab-label">{shortLabel(item.label)}</span>
            </button>
          ))}
          <button
            className={`mobile-nav-tab${isMoreActive ? ' active' : ''}`}
            onClick={() => drawerOpen ? closeDrawer() : openDrawer()}
          >
            <span className="mobile-nav-tab-icon">
              {MORE_ICON}
              {moreStatus && (
                <span className={`health-dot health-dot--${moreStatus} nav-status-dot nav-status-dot--corner`} aria-hidden />
              )}
            </span>
            <span className="mobile-nav-tab-label">More</span>
          </button>
        </div>

        {drawerOpen && (
          <>
            <div
              className={`mobile-drawer-backdrop${drawerVisible ? ' open' : ''}`}
              onClick={() => closeDrawer()}
            />
            <div className={`mobile-drawer${drawerVisible ? ' open' : ''}`}>
              <div className="mobile-drawer-handle" />
              {drawerSections.map((section, si) => (
                <div key={si} className="mobile-drawer-section">
                  {section.label && (
                    <div className="mobile-drawer-section-label">{section.label}</div>
                  )}
                  {section.items.map(item => (
                    <button
                      key={item.view}
                      className={`mobile-drawer-item${activeView === item.view ? ' active' : ''}`}
                      onClick={() => navigateFrom(item.view)}
                    >
                      <span className="mobile-drawer-item-icon">{item.icon}</span>
                      <span>{item.label}</span>
                      {statusDots?.[item.view] && (
                        <span className={`health-dot health-dot--${statusDots[item.view]} nav-status-dot`} aria-hidden />
                      )}
                    </button>
                  ))}
                </div>
              ))}
              <div className="mobile-drawer-signout">
                <button onClick={signOut}>Sign Out</button>
              </div>
            </div>
          </>
        )}
      </>
    );
  }

  return (
    <div className={`sidebar${collapsed ? ' collapsed' : ''}`}>
      {/* Logo: links back to main site */}
      <a href="https://nysterys.com" className="sidebar-logo" rel="noopener noreferrer">
        <span className="sidebar-logo-wordmark">
          NYS<span>T</span>ERYS
          <span className="sidebar-logo-sub">Team Portal</span>
        </span>
        <span className="sidebar-logo-monogram">T</span>
      </a>

      <div className="sidebar-user">
        <div className="sidebar-user-name">{profile?.full_name}</div>
        <div className="sidebar-user-role">
          {profile?.role === 'admin' ? 'Manager' : profile?.creator_name || 'Creator'}
        </div>
      </div>

      <nav className="sidebar-nav">
        {navItems.map((section, si) => (
          <div key={si} style={{ display: 'contents' }}>
            {section.label && (
              <div className="nav-section-label">{section.label}</div>
            )}
            {section.items.map(item => (
              <button
                key={item.view}
                type="button"
                className={`nav-item ${activeView === item.view ? 'active' : ''}`}
                onClick={() => setActiveView(item.view)}
                data-tooltip={item.label}
                aria-label={item.label}
              >
                <span className="nav-item-icon">{item.icon}</span>
                <span className="nav-label">{item.label}</span>
                {statusDots?.[item.view] && (
                  <span className={`health-dot health-dot--${statusDots[item.view]} nav-status-dot`} aria-hidden />
                )}
              </button>
            ))}
          </div>
        ))}
        {/* Sign out: only visible in mobile bottom nav */}
        <button type="button" className="nav-item nav-item-signout" onClick={signOut} aria-label="Sign out">
          <span className="nav-item-icon">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>
          </span>
          Sign Out
        </button>
      </nav>

      <div className="sidebar-footer">
        <a
          href="https://nysterys.com"
          className="sidebar-back-link"
          rel="noopener noreferrer"
        >
          ← nysterys.com
        </a>
        <div className="sidebar-footer-right">
          {secondsLeft != null && (
            <span className="sidebar-idle" style={{
              color: secondsLeft < 120 ? 'var(--orange)' : 'var(--dim)',
            }}>
              {fmtIdle(secondsLeft)}
            </span>
          )}
          <button className="btn-signout" onClick={signOut}>Sign Out</button>
        </div>
        <button
          className="sidebar-toggle"
          onClick={() => setCollapsed(c => !c)}
          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          {collapsed ? (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
          ) : (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
          )}
        </button>
      </div>
    </div>
  );
}
