/**
 * utils/period.js - date-range period filtering for reporting views.
 *
 * Defines the named periods ('all' | 'ytd' | 'qtd' | 'lastq' | 'lastyear' |
 * 'YYYY-MM'), the inPeriod() predicate that tests a date string against one, the
 * option list, and the <PeriodSelect> dropdown. Used by ledger/analytics/expense
 * views that filter rows by a chosen window.
 *
 * @gotcha inPeriod compares lexicographic 'YYYY-MM-DD' string slices, never
 *         Date objects, specifically to dodge the new Date('YYYY-MM-DD') UTC-
 *         midnight off-by-one. Keep new comparisons string-based.
 */
import { fmtMonth } from './format';

/** Current month as 'YYYY-MM' (local time). */
export function thisMonth() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

export function lastMonth() {
  const d = new Date();
  d.setMonth(d.getMonth() - 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

/**
 * Local 'YYYY-MM-DD' from the parts, never toISOString: that one gives the UTC date, and a
 * local midnight east of UTC is the evening BEFORE in UTC, so every quarter boundary landed
 * a day early. Same shape as todayYMD() in utils/format.js.
 */
function ymd(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** First day of the quarter the clock is in, as the same 'YYYY-MM-DD' its caller compares. */
function currentQuarterStart() {
  const now = new Date();
  return ymd(new Date(now.getFullYear(), Math.floor(now.getMonth() / 3) * 3, 1));
}

function lastQuarterRange() {
  const now = new Date();
  const q = Math.floor(now.getMonth() / 3);
  const sy = q === 0 ? now.getFullYear() - 1 : now.getFullYear();
  const sm = q === 0 ? 9 : (q - 1) * 3;
  return { start: ymd(new Date(sy, sm, 1)), end: ymd(new Date(sy, sm + 3, 0)) };
}

/**
 * True when a date falls inside a named period.
 *
 * @param {string} dateStr - any 'YYYY-MM-DD...' string (time portion ignored)
 * @param {string} period - 'all' | 'ytd' | 'qtd' | 'lastq' | 'lastyear' | 'YYYY-MM'
 * @returns {boolean} 'all' always true; a bare 'YYYY-MM' matches that month.
 */
export function inPeriod(dateStr, period) {
  if (period === 'all') return true;
  if (!dateStr) return false;
  const d = dateStr.slice(0, 10);
  if (period === 'ytd')      return d >= `${new Date().getFullYear()}-01-01`;
  if (period === 'lastyear') return d.startsWith(String(new Date().getFullYear() - 1));
  if (period === 'qtd')      return d >= currentQuarterStart();
  if (period === 'lastq')    { const { start, end } = lastQuarterRange(); return d >= start && d <= end; }
  return d.startsWith(period);
}

/**
 * Build the <select> option list: fixed presets followed by each concrete month.
 *
 * @param {string[]} months - 'YYYY-MM' values present in the data, newest first.
 * @param {string} [selected] - the period currently in state.
 * @returns {{value: string, label: string}[]}
 * @gotcha `selected` is not decoration. `months` comes from the rows on screen, so a chosen
 *         month can vanish from it (the last row in it gets re-dated, or the page opens on a
 *         month the data has not reached yet). A <select> whose value matches no option does
 *         not go blank: React selects the FIRST option instead, so the control read "All time"
 *         while the state still filtered to an empty month and hid all 81 payments behind
 *         copy blaming filters the reader could not see. A month named here is a month the
 *         list offers, so the control can only ever say what it is actually doing.
 */
export function buildPeriodOptions(months, selected) {
  const withSelected = /^\d{4}-\d{2}$/.test(selected || '') && !months.includes(selected)
    ? [...months, selected].sort().reverse()
    : months;
  return [
    { value: 'all',      label: 'All time' },
    { value: 'ytd',      label: 'Year to date' },
    { value: 'qtd',      label: 'Quarter to date' },
    { value: 'lastq',    label: 'Last quarter' },
    { value: 'lastyear', label: 'Last year' },
    ...withSelected.map(m => ({ value: m, label: fmtMonth(m) })),
  ];
}

/** Period dropdown. `months` is the list of concrete 'YYYY-MM' values to offer. */
export function PeriodSelect({ period, onChange, months, style }) {
  return (
    <select
      className="form-select"
      aria-label="Period"
      style={{ width: 'auto', padding: '5px 10px', fontSize: 12, ...style }}
      value={period}
      onChange={e => onChange(e.target.value)}
    >
      {buildPeriodOptions(months, period).map(o => (
        <option key={o.value} value={o.value}>{o.label}</option>
      ))}
    </select>
  );
}
